      url: `${withoutTrailingSlash(settings.baseUrl)}/messages`,
      init: {
        method: "POST",
        headers: commonHeaders,
        signal,
        body: JSON.stringify({
          model: settings.model,
          system: systemPrompt,
          max_tokens: 4096,
          temperature: settings.temperature,
          ...(stream ? { stream: true } : {}),
          messages: history.map((message) => ({ role: message.role, content: message.content })),
        }),
