export function parseInteractiveSegments(text: string): InteractiveSegment[] {
  const segments: InteractiveSegment[] = [];
  let lastIndex = 0;

  const pushText = (content: string) => {
    if (content.trim().length > 0) segments.push({ type: "text", content });
  };

